232	    private HttpResponse<String> verificaDocumento(HttpClient httpClient, String accessToken, byte[] fileBytes, long tsDateValidity)
233	            throws Exception {
234	
235	        String boundary = "----FdrVerificaTestBoundary" + System.nanoTime();
236	        byte[] body = buildMultipartFilePart(boundary, fileBytes);
237	
238	        String url = String.format(VERIFICA_URL, tsDateValidity);
239	
240	        HttpRequest request = HttpRequest.newBuilder()
241	                .uri(new URI(url))
242	                .method("POST", HttpRequest.BodyPublishers.ofByteArray(body))
243	                .header("Accept", "application/json")
244	                .header("Authorization", "Bearer " + accessToken)
245	                .header("Content-Type", "multipart/form-data; boundary=" + boundary)
246	                .timeout(REQUEST_TIMEOUT)
247	                .build();
248	
249	        return httpClient.send(request, HttpResponse.BodyHandlers.ofString());
250	    }
