252	    private byte[] buildMultipartFilePart(String boundary, byte[] fileBytes) throws Exception {
253	        String header = "--" + boundary + "\r\n"
254	                + "Content-Disposition: form-data; name=\"file\"; filename=\"" + RESOURCE_FILE.substring(1) + "\"\r\n"
255	                + "Content-Type: " + FILE_MIME + "\r\n\r\n";
256	        String footer = "\r\n--" + boundary + "--\r\n";
257	
258	        ByteArrayOutputStream out = new ByteArrayOutputStream();
259	        out.write(header.getBytes(StandardCharsets.UTF_8));
260	        out.write(fileBytes);
261	        out.write(footer.getBytes(StandardCharsets.UTF_8));
262	        return out.toByteArray();
263	    }
