274	    private String estraiAccessToken(String json) {
275	        if (json == null) {
276	            return null;
277	        }
278	        Matcher matcher = Pattern.compile("\"access_token\"\\s*:\\s*\"([^\"]+)\"").matcher(json);
279	        return matcher.find() ? matcher.group(1) : null;
280	    }
