283	        if (json == null) {
284	            return null;
285	        }
286	        Matcher matcher = Pattern.compile("\"dataFineValidita\"\\s*:\\s*\"([^\"]+)\"").matcher(json);
287	        return matcher.find() ? matcher.group(1) : null;
288	    }
