290	    private HttpResponse<byte[]> firmaDocumento(HttpClient httpClient, String accessToken, byte[] pdfBytes)
291	            throws Exception {
292	
293	        String authJson = buildAuthJson();
294	        String padesParamJson = buildPadesParamJson();
295	
296	        String boundary = "----FdrFirmaTestBoundary" + System.nanoTime();
297	        byte[] body = buildMultipartFirma(boundary, pdfBytes, authJson, padesParamJson);
298	
299	        HttpRequest request = HttpRequest.newBuilder()
300	                .uri(new URI(APPOSIZIONE_URL))
301	                .method("POST", HttpRequest.BodyPublishers.ofByteArray(body))
302	                .header("Accept", "application/pdf")
303	                .header("Authorization", "Bearer " + accessToken)
304	                .header("Content-Type", "multipart/form-data; boundary=" + boundary)
305	                .timeout(REQUEST_TIMEOUT)
306	                .build();
307	
308	        return httpClient.send(request, HttpResponse.BodyHandlers.ofByteArray());
309	    }
