311	    private String buildAuthJson() {
312	        StringBuilder json = new StringBuilder("{");
313	        json.append("\"codiceFiscale\":\"").append(SIGN_CODICE_FISCALE).append("\",");
314	        json.append("\"codiceCertificato\":\"").append(SIGN_CODICE_CERTIFICATO).append("\",");
315	        json.append("\"password\":\"").append(SIGN_PASSWORD).append("\",");
316	        if (SIGN_OTP != null && !SIGN_OTP.isEmpty()) {
317	            json.append("\"otp\":\"").append(SIGN_OTP).append("\"");
318	        } else {
319	            json.append("\"otp\":null");
320	        }
321	        json.append("}");
322	        return json.toString();
323	    }
324	
325	    private String buildPadesParamJson() {
326	        return "{\"flagVisibile\":false,\"page\":0,\"leftx\":0,\"lefty\":0,\"rightx\":0,\"righty\":0,\"padesProfile\":\"PADESBES\"}";
327	    }
328	
329	    private byte[] buildMultipartFirma(String boundary, byte[] pdfBytes, String authJson, String padesParamJson)
330	            throws Exception {
331	
332	        ByteArrayOutputStream out = new ByteArrayOutputStream();
333	        writePart(out, boundary, "file", FILE_MIME, pdfBytes);
334	        writePart(out, boundary, "auth", "application/json", authJson.getBytes(StandardCharsets.UTF_8));
335	        writePart(out, boundary, "padesParam", "application/json", padesParamJson.getBytes(StandardCharsets.UTF_8));
336	        out.write(("--" + boundary + "--\r\n").getBytes(StandardCharsets.UTF_8));
337	        return out.toByteArray();
338	    }
339	
340	    private void writePart(ByteArrayOutputStream out, String boundary, String name, String contentType, byte[] content)
341	            throws Exception {
342	
343	        String header = "--" + boundary + "\r\n"
344	                + "Content-Disposition: form-data; name=\"" + name + "\"\r\n"
345	                + "Content-Type: " + contentType + "\r\n\r\n";
346	        out.write(header.getBytes(StandardCharsets.UTF_8));
347	        out.write(content);
348	        out.write("\r\n".getBytes(StandardCharsets.UTF_8));
349	    }
350	
351	
352	    private long dateToEpochTest(String valoreNodoDataFineValidita) {
353	        try {
354	            SimpleDateFormat sdf = new SimpleDateFormat("EEE MMM dd HH:mm:ss zzz yyyy", Locale.ENGLISH);
355	            Date dataFine = sdf.parse(valoreNodoDataFineValidita);
356	            return dataFine.getTime();
357	        } catch (ParseException e) {
358	            throw new RuntimeException(e);
359	        }
360	    }
361	}
